<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

final class TemplateSnippetTenantVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new TenantRef('one');
        $ref = TemplateSnippetTenantVO::from($value);
        $this->assertEquals(new TenantRef('one'), $ref->value());
        $other = TemplateSnippetTenantVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TemplateSnippetTenantVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TemplateSnippetTenantVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TemplateSnippetTenantVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TemplateSnippetTenantVO::from(new TenantRef('one'));
        $same = TemplateSnippetTenantVO::from(new TenantRef('one'));
        $other = TemplateSnippetTenantVO::from(new TenantRef('other'));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
